create schema if not exists private;
create table if not exists public.tool_traceability_presence(workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,location jsonb not null default '{}'::jsonb,last_seen_at timestamptz not null default now(),primary key(workspace_id,user_id));
create table if not exists public.tool_traceability_notifications(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,target_user_id uuid not null references public.profiles(id) on delete cascade,request_id text,message text not null check(char_length(message) between 1 and 2000),seen_at timestamptz,created_at timestamptz not null default now());
create or replace function private.tool_traceability_can_manage(p_workspace_id uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select coalesce(private.tool_traceability_current_role(p_workspace_id) in('ADMIN','LOGISTICS'),false) $$;
create or replace function private.tool_traceability_can_create(p_workspace_id uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select coalesce(private.tool_traceability_current_role(p_workspace_id) in('ADMIN','LOGISTICS','USER'),false) $$;
create or replace function private.tool_traceability_can_comment(p_workspace_id uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select coalesce(private.tool_traceability_current_role(p_workspace_id) in('ADMIN','LOGISTICS','USER'),false) $$;
create or replace function public.tool_traceability_list_items(p_workspace_id uuid,p_board text,p_where jsonb default '{}'::jsonb,p_sort jsonb default '{}'::jsonb,p_limit int default 50,p_cursor text default null,p_include_updates boolean default false) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare r jsonb; search_text text:=coalesce(p_where#>>'{name,contains}',p_where->>'search',''); begin if p_board='tools' then return public.tool_traceability_list_tools(p_workspace_id,search_text,p_where->>'category',p_where->>'availability',p_limit,p_cursor); end if; r:=public.tool_traceability_list_requests(p_workspace_id,search_text,p_where->>'requestStatus',p_where->>'extensionState',p_limit,p_cursor); if p_include_updates then r:=jsonb_set(r,'{items}',coalesce((select jsonb_agg(i.obj || jsonb_build_object('updates',coalesce((select jsonb_agg(jsonb_build_object('id',u.id::text,'text_body',u.text_body,'creator',private.tool_traceability_profile_json(u.creator_user_id),'created_at',u.created_at,'assets',coalesce((select jsonb_agg(jsonb_build_object('id',a.id::text,'name',a.name,'storagePath',a.storage_path,'mime_type',a.mime_type,'file_size',a.size_bytes)) from public.tool_traceability_attachments a where a.update_id=u.id),'[]'::jsonb)) order by u.created_at) from public.tool_traceability_updates u where u.workspace_id=p_workspace_id and u.request_id=i.obj->>'id'),'[]'::jsonb))) from jsonb_array_elements(r->'items') i(obj)),'[]'::jsonb),true); end if; return r; end $$;
create or replace function public.tool_traceability_get_item(p_workspace_id uuid,p_board text,p_item_id text,p_include_updates boolean default false) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare r jsonb; begin r:=public.tool_traceability_get_item(p_workspace_id,p_board,p_item_id); if p_board='requests' and p_include_updates then r:=r||jsonb_build_object('updates',coalesce((select jsonb_agg(jsonb_build_object('id',u.id::text,'text_body',u.text_body,'creator',private.tool_traceability_profile_json(u.creator_user_id),'created_at',u.created_at,'assets',coalesce((select jsonb_agg(jsonb_build_object('id',a.id::text,'name',a.name,'storagePath',a.storage_path,'mime_type',a.mime_type,'file_size',a.size_bytes)) from public.tool_traceability_attachments a where a.update_id=u.id),'[]'::jsonb)) order by u.created_at) from public.tool_traceability_updates u where u.workspace_id=p_workspace_id and u.request_id=p_item_id),'[]'::jsonb)); end if; return r; end $$;
create or replace function public.tool_traceability_create_item(p_workspace_id uuid,p_board text,p_fields jsonb) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ begin if p_board='tools' then return public.tool_traceability_create_tool(p_workspace_id,p_fields); else return public.tool_traceability_create_request(p_workspace_id,p_fields-'_group'-'_returnColumns'||jsonb_build_object('toolQuantities',coalesce(p_fields->'_toolQuantities','{}'::jsonb))); end if; end $$;
create or replace function public.tool_traceability_update_item(p_workspace_id uuid,p_board text,p_item_id text,p_updates jsonb,p_expected_version bigint default null) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ begin if p_board='tools' then return public.tool_traceability_update_tool(p_workspace_id,p_item_id,p_updates-'version'); else return public.tool_traceability_update_request(p_workspace_id,p_item_id,p_updates-'version',p_expected_version); end if; end $$;
create or replace function public.tool_traceability_archive_item(p_workspace_id uuid,p_board text,p_item_id text) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ begin if p_board='tools' then return public.tool_traceability_archive_tool(p_workspace_id,p_item_id); end if; if not private.tool_traceability_can_manage(p_workspace_id) then raise exception 'archive denied' using errcode='42501'; end if; update public.tool_traceability_requests set archived_at=now(),updated_at=now(),version=version+1 where workspace_id=p_workspace_id and id=p_item_id and archived_at is null; return jsonb_build_object('ok',true,'id',p_item_id); end $$;
create or replace function public.tool_traceability_approve_request(p_workspace_id uuid,p_request_id text,p_expected_version bigint default null) returns jsonb language sql security definer set search_path=public,private,pg_temp as $$ select public.tool_traceability_update_request(p_workspace_id,p_request_id,jsonb_build_object('requestStatus','Borrowed'),p_expected_version) $$;
create or replace function public.tool_traceability_reject_request(p_workspace_id uuid,p_request_id text,p_reason text default null,p_expected_version bigint default null) returns jsonb language sql security definer set search_path=public,private,pg_temp as $$ select public.tool_traceability_update_request(p_workspace_id,p_request_id,jsonb_build_object('requestStatus','Rejected','rejectionReason',p_reason),p_expected_version) $$;
create or replace function public.tool_traceability_resubmit_request(p_workspace_id uuid,p_request_id text,p_expected_version bigint default null) returns jsonb language sql security definer set search_path=public,private,pg_temp as $$ select public.tool_traceability_update_request(p_workspace_id,p_request_id,jsonb_build_object('requestStatus','Pending Approval','extensionState','None'),p_expected_version) $$;
create or replace function public.tool_traceability_return_request(p_workspace_id uuid,p_request_id text,p_tool_ids jsonb default null,p_full_return boolean default true,p_return_date date default current_date,p_expected_version bigint default null) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ begin if coalesce(p_full_return,true) or p_tool_ids is null then return public.tool_traceability_update_request(p_workspace_id,p_request_id,jsonb_build_object('requestStatus','Returned','actualReturn',p_return_date),p_expected_version); end if; if not private.tool_traceability_can_manage(p_workspace_id) then raise exception 'return denied' using errcode='42501'; end if; update public.tool_traceability_request_tools set returned_at=now() where workspace_id=p_workspace_id and request_id=p_request_id and tool_id in(select jsonb_array_elements_text(p_tool_ids)); update public.tool_traceability_tools t set availability='Returned',assigned_to='[]'::jsonb,current_request_id=null,updated_at=now(),version=version+1 from public.tool_traceability_request_tools rt where rt.workspace_id=p_workspace_id and rt.request_id=p_request_id and rt.returned_at is not null and t.workspace_id=rt.workspace_id and t.id=rt.tool_id; return public.tool_traceability_get_item(p_workspace_id,'requests',p_request_id); end $$;
create or replace function public.tool_traceability_set_extension(p_workspace_id uuid,p_request_id text,p_state text,p_new_to date default null,p_expected_version bigint default null) returns jsonb language sql security definer set search_path=public,private,pg_temp as $$ select public.tool_traceability_update_request(p_workspace_id,p_request_id,jsonb_strip_nulls(jsonb_build_object('extensionState',p_state,'borrowWindow',case when p_new_to is null then null else jsonb_build_object('to',p_new_to) end)),p_expected_version) $$;
create or replace function public.tool_traceability_aggregate(p_workspace_id uuid,p_board text,p_group_by text default null) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ begin if not private.tool_traceability_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; if p_board='requests' and p_group_by='requestStatus' then return coalesce((select jsonb_agg(jsonb_build_object('requestStatus',request_status,'count',c)) from(select request_status,count(*) c from public.tool_traceability_requests where workspace_id=p_workspace_id and archived_at is null group by request_status)x),'[]'::jsonb); elsif p_board='tools' and p_group_by='availability' then return coalesce((select jsonb_agg(jsonb_build_object('availability',availability,'count',c)) from(select availability,count(*) c from public.tool_traceability_tools where workspace_id=p_workspace_id and archived_at is null group by availability)x),'[]'::jsonb); elsif p_board='requests' then return jsonb_build_array(jsonb_build_object('count',(select count(*) from public.tool_traceability_requests where workspace_id=p_workspace_id and archived_at is null))); else return jsonb_build_array(jsonb_build_object('count',(select count(*) from public.tool_traceability_tools where workspace_id=p_workspace_id and archived_at is null))); end if; end $$;
create or replace function public.tool_traceability_add_update(p_workspace_id uuid,p_request_id text,p_text text) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare u public.tool_traceability_updates%rowtype; begin if not private.tool_traceability_can_comment(p_workspace_id) then raise exception 'comment denied' using errcode='42501'; end if; insert into public.tool_traceability_updates(workspace_id,request_id,creator_user_id,text_body) values(p_workspace_id,p_request_id,auth.uid(),left(trim(p_text),8000)) returning * into u; return jsonb_build_object('id',u.id::text,'text_body',u.text_body,'creator',private.tool_traceability_profile_json(u.creator_user_id),'created_at',u.created_at,'assets','[]'::jsonb); end $$;
create or replace function public.tool_traceability_register_attachment(p_workspace_id uuid,p_request_id text,p_update_id uuid,p_storage_path text,p_name text,p_mime_type text,p_size_bytes bigint) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare a public.tool_traceability_attachments%rowtype; begin if not private.tool_traceability_can_comment(p_workspace_id) then raise exception 'attachment denied' using errcode='42501'; end if; if p_size_bytes<1 or p_size_bytes>10485760 then raise exception 'invalid attachment size' using errcode='22023'; end if; if p_storage_path not like p_workspace_id::text||'/'||p_request_id||'/%' then raise exception 'invalid attachment path' using errcode='22023'; end if; if p_update_id is not null and not exists(select 1 from public.tool_traceability_updates where id=p_update_id and workspace_id=p_workspace_id and request_id=p_request_id) then raise exception 'attachment update/request mismatch' using errcode='22023'; end if; insert into public.tool_traceability_attachments(workspace_id,request_id,update_id,storage_path,name,mime_type,size_bytes,creator_user_id) values(p_workspace_id,p_request_id,p_update_id,p_storage_path,left(p_name,500),left(coalesce(p_mime_type,'application/octet-stream'),200),p_size_bytes,auth.uid()) returning * into a; return jsonb_build_object('id',a.id::text,'name',a.name,'storagePath',a.storage_path,'mime_type',a.mime_type,'file_size',a.size_bytes); end $$;
create or replace function public.tool_traceability_state_get(p_workspace_id uuid,p_key text) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare r public.tool_traceability_state%rowtype; u uuid:=coalesce(auth.uid(),'00000000-0000-0000-0000-000000000000'::uuid); begin if not private.tool_traceability_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; select * into r from public.tool_traceability_state where workspace_id=p_workspace_id and key=p_key and user_id=u; return jsonb_build_object('value',r.value,'version',coalesce(r.version,0)); end $$;
create or replace function public.tool_traceability_state_put(p_workspace_id uuid,p_key text,p_value jsonb,p_version bigint default null) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare u uuid:=auth.uid(); r public.tool_traceability_state%rowtype; begin if not private.tool_traceability_can_create(p_workspace_id) then raise exception 'state write denied' using errcode='42501'; end if; select * into r from public.tool_traceability_state where workspace_id=p_workspace_id and key=p_key and user_id=u for update; if found and p_version is not null and r.version<>p_version then raise exception 'version conflict' using errcode='40001'; end if; insert into public.tool_traceability_state(workspace_id,user_id,key,value,version,updated_at) values(p_workspace_id,u,p_key,p_value,1,now()) on conflict(workspace_id,key,user_id) do update set value=excluded.value,version=public.tool_traceability_state.version+1,updated_at=now() returning * into r; return jsonb_build_object('value',r.value,'version',r.version); end $$;
create or replace function public.tool_traceability_inventory_snapshot(p_workspace_id uuid) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ begin if not private.tool_traceability_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; return jsonb_build_object('stockLevels',coalesce((select jsonb_object_agg(id,stock_quantity) from public.tool_traceability_tools where workspace_id=p_workspace_id and archived_at is null),'{}'::jsonb),'borrowedCounts',coalesce((select jsonb_object_agg(id,borrowed_quantity) from public.tool_traceability_tools where workspace_id=p_workspace_id and archived_at is null),'{}'::jsonb),'requestQuantities',coalesce((select jsonb_object_agg(request_id,q) from(select request_id,jsonb_object_agg(tool_id,quantity) q from public.tool_traceability_request_tools where workspace_id=p_workspace_id and returned_at is null group by request_id)x),'{}'::jsonb)); end $$;
create or replace function public.tool_traceability_inventory_set_stock(p_workspace_id uuid,p_tool_id text,p_quantity int) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ begin if not private.tool_traceability_can_manage(p_workspace_id) then raise exception 'inventory management denied' using errcode='42501'; end if; if p_quantity<0 then raise exception 'quantity must be nonnegative' using errcode='22023'; end if; update public.tool_traceability_tools set stock_quantity=p_quantity,updated_at=now(),version=version+1 where workspace_id=p_workspace_id and id=p_tool_id and archived_at is null and borrowed_quantity<=p_quantity; if not found then raise exception 'tool not found or quantity below borrowed amount' using errcode='22023'; end if; return public.tool_traceability_inventory_snapshot(p_workspace_id); end $$;
create or replace function public.tool_traceability_inventory_reserve(p_workspace_id uuid,p_request_id text,p_quantities jsonb) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare k text; v text; q int; begin if not private.tool_traceability_can_create(p_workspace_id) then raise exception 'reserve denied' using errcode='42501'; end if; for k,v in select * from jsonb_each_text(coalesce(p_quantities,'{}'::jsonb)) loop q:=greatest(v::int,1); update public.tool_traceability_request_tools set quantity=q where workspace_id=p_workspace_id and request_id=p_request_id and tool_id=k; perform private.tool_traceability_recalc_inventory(p_workspace_id,k); end loop; return public.tool_traceability_inventory_snapshot(p_workspace_id); end $$;
create or replace function public.tool_traceability_inventory_release(p_workspace_id uuid,p_request_id text,p_tool_ids jsonb default null) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare tid text; begin if not private.tool_traceability_can_manage(p_workspace_id) then raise exception 'release denied' using errcode='42501'; end if; if p_tool_ids is null then update public.tool_traceability_request_tools set returned_at=coalesce(returned_at,now()) where workspace_id=p_workspace_id and request_id=p_request_id; else update public.tool_traceability_request_tools set returned_at=coalesce(returned_at,now()) where workspace_id=p_workspace_id and request_id=p_request_id and tool_id in(select jsonb_array_elements_text(p_tool_ids)); end if; for tid in select tool_id from public.tool_traceability_request_tools where workspace_id=p_workspace_id and request_id=p_request_id loop perform private.tool_traceability_recalc_inventory(p_workspace_id,tid); end loop; return public.tool_traceability_inventory_snapshot(p_workspace_id); end $$;
create or replace function public.tool_traceability_presence_heartbeat(p_workspace_id uuid,p_location jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ begin if not private.tool_traceability_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; insert into public.tool_traceability_presence(workspace_id,user_id,location,last_seen_at) values(p_workspace_id,auth.uid(),coalesce(p_location,'{}'::jsonb),now()) on conflict(workspace_id,user_id) do update set location=excluded.location,last_seen_at=now(); return jsonb_build_object('ok',true); end $$;
create or replace function public.tool_traceability_presence_leave(p_workspace_id uuid) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ begin delete from public.tool_traceability_presence where workspace_id=p_workspace_id and user_id=auth.uid(); return jsonb_build_object('ok',true); end $$;
create or replace function public.tool_traceability_presence_list(p_workspace_id uuid) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ begin if not private.tool_traceability_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; return coalesce((select jsonb_agg(private.tool_traceability_profile_json(p.user_id)||jsonb_build_object('location',p.location,'lastSeenAt',p.last_seen_at)) from public.tool_traceability_presence p where p.workspace_id=p_workspace_id and p.last_seen_at>now()-interval '2 minutes'),'[]'::jsonb); end $$;
create or replace function public.tool_traceability_activity_list(p_workspace_id uuid,p_limit int default 100) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ begin if not private.tool_traceability_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; return coalesce((select jsonb_agg(jsonb_build_object('id',a.id::text,'entityType',a.entity_type,'entityId',a.entity_id,'eventType',a.event_type,'detail',a.detail,'createdAt',a.created_at,'actor',case when a.actor_user_id is null then null else private.tool_traceability_profile_json(a.actor_user_id) end) order by a.created_at desc) from(select * from public.tool_traceability_activity where workspace_id=p_workspace_id order by created_at desc limit greatest(1,least(coalesce(p_limit,100),500)))a),'[]'::jsonb); end $$;
create or replace function public.tool_traceability_notify(p_workspace_id uuid,p_request_id text,p_target_user_id uuid,p_message text) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare n public.tool_traceability_notifications%rowtype; begin if not private.tool_traceability_can_comment(p_workspace_id) then raise exception 'notification denied' using errcode='42501'; end if; insert into public.tool_traceability_notifications(workspace_id,target_user_id,request_id,message) values(p_workspace_id,p_target_user_id,p_request_id,left(p_message,2000)) returning * into n; return jsonb_build_object('id',n.id::text,'createdAt',n.created_at); end $$;
create or replace function public.tool_traceability_admin_set_role(p_workspace_id uuid,p_user_id uuid,p_role text,p_enabled boolean default true) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare r text:=upper(trim(p_role)); begin if not private.tool_traceability_is_admin(p_workspace_id) then raise exception 'admin required' using errcode='42501'; end if; if r not in('ADMIN','LOGISTICS','USER','VIEWER') then raise exception 'invalid role' using errcode='22023'; end if; if not exists(select 1 from public.workspace_members where workspace_id=p_workspace_id and user_id=p_user_id and active=true) then raise exception 'active Workspace membership required' using errcode='22023'; end if; insert into public.tool_traceability_memberships(workspace_id,user_id,role,enabled,status,assigned_by) values(p_workspace_id,p_user_id,r,p_enabled,case when p_enabled then 'active' else 'disabled' end,auth.uid()) on conflict(workspace_id,user_id) do update set role=excluded.role,enabled=excluded.enabled,status=excluded.status,assigned_by=auth.uid(),updated_at=now(); return jsonb_build_object('workspaceId',p_workspace_id,'userId',p_user_id,'role',r,'enabled',p_enabled); end $$;
alter table public.tool_traceability_memberships enable row level security; alter table public.tool_traceability_tools enable row level security; alter table public.tool_traceability_requests enable row level security; alter table public.tool_traceability_request_tools enable row level security; alter table public.tool_traceability_updates enable row level security; alter table public.tool_traceability_attachments enable row level security; alter table public.tool_traceability_activity enable row level security; alter table public.tool_traceability_state enable row level security; alter table public.tool_traceability_reference_counters enable row level security; alter table public.tool_traceability_presence enable row level security; alter table public.tool_traceability_notifications enable row level security;
revoke all on public.tool_traceability_memberships,public.tool_traceability_tools,public.tool_traceability_requests,public.tool_traceability_request_tools,public.tool_traceability_updates,public.tool_traceability_attachments,public.tool_traceability_activity,public.tool_traceability_state,public.tool_traceability_reference_counters,public.tool_traceability_presence,public.tool_traceability_notifications from anon,authenticated;
insert into storage.buckets(id,name,public,file_size_limit) values('tool-traceability-attachments','tool-traceability-attachments',false,10485760) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit;
drop policy if exists tool_traceability_storage_select on storage.objects; drop policy if exists tool_traceability_storage_insert on storage.objects; drop policy if exists tool_traceability_storage_delete on storage.objects;
create policy tool_traceability_storage_select on storage.objects for select to authenticated using(bucket_id='tool-traceability-attachments' and private.tool_traceability_has_access(((storage.foldername(name))[1])::uuid));
create policy tool_traceability_storage_insert on storage.objects for insert to authenticated with check(bucket_id='tool-traceability-attachments' and private.tool_traceability_can_comment(((storage.foldername(name))[1])::uuid));
create policy tool_traceability_storage_delete on storage.objects for delete to authenticated using(bucket_id='tool-traceability-attachments' and private.tool_traceability_can_manage(((storage.foldername(name))[1])::uuid));
do $$ declare f record; begin for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname like 'tool_traceability_%' loop execute format('revoke all on function %s from public,anon,authenticated',f.sig); end loop; for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'tool_traceability_%' loop execute format('revoke all on function %s from public,anon',f.sig); execute format('grant execute on function %s to authenticated',f.sig); end loop; end $$;;
